#include "hhs_p183.h"
#include <stdio.h>
#include <string.h>
#define REQUIRE(c) do{if(!(c)){fprintf(stderr,"FAIL:%s:%d:%s\n",__FILE__,__LINE__,#c);return 1;}}while(0)
int main(void){hhs_p183_context*ctx=hhs_p183_context_create();char id[65],forward[128],reciprocal[128],receipt[73],hash216[217];uint32_t residue=0;int scalar=0;const char*formula=hhs_p183_canonical_formula();
REQUIRE(ctx!=NULL);REQUIRE(hhs_p183_global_modulus()==1259713u);REQUIRE(hhs_p183_factorial72_modulus_gcd()==91u);REQUIRE(strlen(hhs_p183_factorial72_decimal())==104u);REQUIRE(strcmp(hhs_p183_forward_lane_token(),"List(x*Factorial(72),(y*(1/Factorial(72))))")==0);REQUIRE(strcmp(hhs_p183_reciprocal_lane_token(),"List((y*(1/Factorial(72))),x*Factorial(72))")==0);
REQUIRE(hhs_p183_parse_equation(ctx,formula,strlen(formula))==P183_OK);REQUIRE(hhs_p183_snapshot_lexical_identity(ctx,id)==P183_OK&&strlen(id)==64u);REQUIRE(hhs_p183_build_membrane_tree(ctx)==P183_OK&&hhs_p183_membrane_count(ctx)>0u);REQUIRE(hhs_p183_validate_membrane_boundaries(ctx)==P183_OK);REQUIRE(hhs_p183_validate_probability_domain(ctx,1)==P183_OK);REQUIRE(hhs_p183_validate_equation_truth(ctx,1)==P183_OK);REQUIRE(hhs_p183_bind_hydration_roles(ctx,"1/2","1/2","1/2","2")==P183_OK);REQUIRE(hhs_p183_hydrate_factorial72_forward(ctx,forward,sizeof(forward))==P183_OK);REQUIRE(hhs_p183_construct_reciprocal_lane(ctx,reciprocal,sizeof(reciprocal))==P183_OK);REQUIRE(strcmp(forward,hhs_p183_forward_lane_token())==0);REQUIRE(strcmp(reciprocal,hhs_p183_reciprocal_lane_token())==0);REQUIRE(hhs_p183_execute_probability_adapter(ctx,"bayes",0)==P183_OK);REQUIRE(hhs_p183_close_u72(ctx)==P183_OK);REQUIRE(hhs_p183_apply_outer_modulus(ctx,1,1u,&residue,&scalar)==P183_OK&&scalar==1&&residue==1u);REQUIRE(hhs_p183_emit_hash72_receipt(ctx,receipt)==P183_OK&&strlen(receipt)==72u);REQUIRE(hhs_p183_compute_hash216_identity(ctx,hash216)==P183_OK&&strlen(hash216)==216u);REQUIRE(hhs_p183_verify_receipt(ctx,receipt)==P183_OK);REQUIRE(hhs_p183_replay(ctx)==P183_OK);receipt[0]=receipt[0]=='0'?'1':'0';REQUIRE(hhs_p183_verify_receipt(ctx,receipt)==P183_REJECT_RECEIPT);hhs_p183_context_destroy(ctx);
ctx=hhs_p183_context_create();REQUIRE(hhs_p183_parse_equation(ctx,"P(A)=(P(B)",strlen("P(A)=(P(B)"))==P183_OK);REQUIRE(hhs_p183_build_membrane_tree(ctx)==P183_REJECT_UNBALANCED_MEMBRANE);hhs_p183_context_destroy(ctx);
ctx=hhs_p183_context_create();REQUIRE(hhs_p183_parse_equation(ctx,"P(A)=P(A)",strlen("P(A)=P(A)"))==P183_OK);REQUIRE(hhs_p183_build_membrane_tree(ctx)==P183_OK);REQUIRE(hhs_p183_validate_membrane_boundaries(ctx)==P183_OK);REQUIRE(hhs_p183_validate_probability_domain(ctx,1)==P183_OK);REQUIRE(hhs_p183_validate_equation_truth(ctx,1)==P183_OK);REQUIRE(hhs_p183_bind_hydration_roles(ctx,"0","0","0","ZERO_BYPASS")==P183_OK);REQUIRE(hhs_p183_execute_probability_adapter(ctx,"independent_intersection",1)==P183_ZERO_BYPASS);REQUIRE(hhs_p183_route_typed_zero(ctx)==P183_ZERO_BYPASS);REQUIRE(hhs_p183_apply_outer_modulus(ctx,0,1u,&residue,&scalar)==P183_OK&&residue==0u&&scalar==1);REQUIRE(hhs_p183_apply_outer_modulus(ctx,1,7u,&residue,&scalar)==P183_REJECT_NONINVERTIBLE_OUTER_DENOMINATOR&&scalar==0);hhs_p183_context_destroy(ctx);puts("HHS_PASS_183_NATIVE_ABI_VERIFIED");return 0;}
